const rows = $input.first().json.rows;

const assets = rows.map(row => ({
  asset_id: row.asset_id,
  shot_id: row.shot_id,
  project_id: row.project_id,
  asset_type: row.asset_type,
  image_path: row.image_path,
  shot_number: row.shot_number,
  shot_type: row.shot_type,
  description: row.description,
  positive_prompt: row.positive_prompt,
  negative_prompt: row.negative_prompt
}));

return [{
  json: {
    assets: assets,
    total_assets: assets.length,
    project_id: rows[0].project_id
  }
}];

const responseText = $input.first().json.response || '{}';
let reviewData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    reviewData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      reviewData = Object.entries(parsed).map(([key, val]) => ({ asset_id: key, ...val }));
    }
  }
} catch (e) {
  reviewData = [];
}

const assets = $('Execute Logic').item.json.assets;
const projectId = $('Execute Logic').item.json.project_id;

const reviewInserts = [];
let passed = 0, needsRepair = 0, rejected = 0;

for (const rd of reviewData) {
  const asset = assets.find(a => a.asset_id === rd.asset_id);
  const overall = rd.overall_score || 0;
  const recommendation = rd.recommendation || 'reject';

  if (recommendation === 'pass') passed++;
  else if (recommendation === 'needs_repair') needsRepair++;
  else rejected++;

  reviewInserts.push({
    json: {
      asset_id: rd.asset_id,
      project_id: projectId,
      overall_score: overall,
      prompt_adherence: rd.prompt_adherence || 0,
      composition: rd.composition || 0,
      style_consistency: rd.style_consistency || 0,
      technical_quality: rd.technical_quality || 0,
      emotional_accuracy: rd.emotional_accuracy || 0,
      issues: JSON.stringify(rd.issues || []),
      recommendation: recommendation,
      repair_notes: rd.repair_notes || null
    }
  });
}

return [{
  json: {
    project_id: projectId,
    reviews: reviewInserts,
    total_reviewed: reviewInserts.length,
    passed: passed,
    needs_repair: needsRepair,
    rejected: rejected
  }
}];

